using MetaheuristicsPlatform.Parameters;
namespace MetaheuristicsPlatform.Algorithms.MultiVerseOptimizer;
public sealed class MultiVerseOptimizerParameters : IMetaheuristicParameters { public int PopulationSize { get; init; }=30; public int MaximumIterations { get; init; }=200; public double WormholeExistenceProbabilityMinimum { get; init; }=0.2; public double WormholeExistenceProbabilityMaximum { get; init; }=1.0; public double ExploitationAccuracy { get; init; }=6.0; public void Validate(){if(PopulationSize<2)throw new ArgumentOutOfRangeException(nameof(PopulationSize));if(MaximumIterations<=0)throw new ArgumentOutOfRangeException(nameof(MaximumIterations));if(!double.IsFinite(WormholeExistenceProbabilityMinimum)||WormholeExistenceProbabilityMinimum<0.0||WormholeExistenceProbabilityMinimum>1.0)throw new ArgumentOutOfRangeException(nameof(WormholeExistenceProbabilityMinimum));if(!double.IsFinite(WormholeExistenceProbabilityMaximum)||WormholeExistenceProbabilityMaximum<WormholeExistenceProbabilityMinimum||WormholeExistenceProbabilityMaximum>1.0)throw new ArgumentOutOfRangeException(nameof(WormholeExistenceProbabilityMaximum));if(!double.IsFinite(ExploitationAccuracy)||ExploitationAccuracy<=0.0)throw new ArgumentOutOfRangeException(nameof(ExploitationAccuracy));} }
